// ─────────────────────────────────────────────
// Core domain types for Health Vault.
//
// These mirror the FastAPI backend's actual Pydantic schemas exactly
// (see backend/app/schemas/*.py and backend/app/models/enums.py) — this file
// is generated by hand from reading that code, not guessed. If the backend
// contract changes, update here first.
// ─────────────────────────────────────────────

// ── Enums ──────────────────────────────────────

export const DocumentType = {
  PRESCRIPTION: 'PRESCRIPTION',
  LAB_REPORT: 'LAB_REPORT',
  MEDICAL_REPORT: 'MEDICAL_REPORT',
  DIAGNOSIS: 'DIAGNOSIS',
  DISCHARGE_SUMMARY: 'DISCHARGE_SUMMARY',
  SCAN_REPORT: 'SCAN_REPORT',
  MEDICAL_BILL: 'MEDICAL_BILL',
  PHARMACY_BILL: 'PHARMACY_BILL',
  INSURANCE_DOCUMENT: 'INSURANCE_DOCUMENT',
  CONSULTATION: 'CONSULTATION',
  OTHER: 'OTHER',
} as const;
export type DocumentType = typeof DocumentType[keyof typeof DocumentType];

export const ProcessingStatus = {
  UPLOADED: 'UPLOADED',
  PROCESSING: 'PROCESSING',
  OCR_COMPLETED: 'OCR_COMPLETED',
  CLASSIFIED: 'CLASSIFIED',
  EXTRACTED: 'EXTRACTED',
  VALIDATED: 'VALIDATED',
  PROCESSED: 'PROCESSED',
  NEEDS_REVIEW: 'NEEDS_REVIEW',
  FAILED: 'FAILED',
} as const;
export type ProcessingStatus = typeof ProcessingStatus[keyof typeof ProcessingStatus];

export const ValidationStatus = {
  VALID: 'VALID',
  NEEDS_REVIEW: 'NEEDS_REVIEW',
  INVALID: 'INVALID',
} as const;
export type ValidationStatus = typeof ValidationStatus[keyof typeof ValidationStatus];

export const ResultFlag = {
  NORMAL: 'NORMAL',
  HIGH: 'HIGH',
  LOW: 'LOW',
  ABNORMAL: 'ABNORMAL',
  CRITICAL: 'CRITICAL',
  UNKNOWN: 'UNKNOWN',
} as const;
export type ResultFlag = typeof ResultFlag[keyof typeof ResultFlag];

export const ExpenseCategory = {
  DOCTOR_CONSULTATION: 'DOCTOR_CONSULTATION',
  MEDICINE: 'MEDICINE',
  LAB_TEST: 'LAB_TEST',
  SCAN: 'SCAN',
  HOSPITALIZATION: 'HOSPITALIZATION',
  SURGERY: 'SURGERY',
  OTHER: 'OTHER',
} as const;
export type ExpenseCategory = typeof ExpenseCategory[keyof typeof ExpenseCategory];

export const TimelineEventType = {
  CONSULTATION: 'CONSULTATION',
  PRESCRIPTION: 'PRESCRIPTION',
  LAB_TEST: 'LAB_TEST',
  DIAGNOSIS: 'DIAGNOSIS',
  SCAN: 'SCAN',
  HOSPITALIZATION: 'HOSPITALIZATION',
  DISCHARGE: 'DISCHARGE',
  MEDICAL_EXPENSE: 'MEDICAL_EXPENSE',
} as const;
export type TimelineEventType = typeof TimelineEventType[keyof typeof TimelineEventType];

export const VaultRole = {
  OWNER: 'OWNER',
  FAMILY_MEMBER: 'FAMILY_MEMBER',
  DOCTOR: 'DOCTOR',
  VIEWER: 'VIEWER',
} as const;
export type VaultRole = typeof VaultRole[keyof typeof VaultRole];

export const MembershipStatus = {
  ACTIVE: 'ACTIVE',
  PENDING: 'PENDING',
  REVOKED: 'REVOKED',
} as const;
export type MembershipStatus = typeof MembershipStatus[keyof typeof MembershipStatus];

export const ShareStatus = {
  ACTIVE: 'ACTIVE',
  REVOKED: 'REVOKED',
  EXPIRED: 'EXPIRED',
} as const;
export type ShareStatus = typeof ShareStatus[keyof typeof ShareStatus];

// ── User & Auth ─────────────────────────────────

export interface User {
  id: string;
  email: string;
  full_name: string;
  phone?: string | null;
  date_of_birth?: string | null;
  gender?: string | null;
  is_active: boolean;
  created_at: string;
}

export interface UserUpdateRequest {
  full_name?: string;
  phone?: string;
  date_of_birth?: string;
  gender?: string;
}

export interface PasswordChangeRequest {
  current_password: string;
  new_password: string;
}

export interface LoginRequest {
  email: string;
  password: string;
}

export interface RegisterRequest {
  email: string;
  password: string;
  full_name: string;
  phone?: string;
}

/** What the frontend works with internally (auth.ts maps the backend's flat
 * token fields into this nested shape so the rest of the app — AuthContext,
 * mocks — doesn't need to change). */
export interface AuthTokens {
  access_token: string;
  refresh_token: string;
  token_type: 'bearer';
}

export interface AuthResponse {
  user: User;
  tokens: AuthTokens;
}

// ── Vault ───────────────────────────────────────

export interface Vault {
  id: string;
  owner_id: string;
  name: string;
  description?: string | null;
  created_at: string;
}

export interface VaultMember {
  id: string;
  vault_id: string;
  user_id: string;
  role: VaultRole;
  status: MembershipStatus;
  created_at: string;
}

export interface VaultDashboard {
  document_count: number;
  documents_needing_review: number;
  documents_by_type: Record<string, number>;
  timeline_event_count: number;
  member_count: number;
  storage_used_bytes: number;
  expense_total: number;
  expense_current_month: number;
  recent_documents: {
    id: string;
    filename: string;
    document_type: DocumentType | null;
    processing_status: ProcessingStatus;
    created_at: string;
  }[];
  recent_timeline_events: { id: string; event_type: TimelineEventType; title: string; event_date: string }[];
}

// ── Documents ───────────────────────────────────

export interface Document {
  id: string;
  vault_id: string;
  original_filename: string;
  mime_type: string;
  file_size_bytes: number;
  document_type: DocumentType | null;
  classification_confidence?: number | null;
  processing_status: ProcessingStatus;
  document_date?: string | null;
  is_archived: boolean;
  created_at: string;
}

export interface DocumentDetail extends Document {
  extracted_text?: string | null;
  doc_metadata?: Record<string, unknown> | null;
}

export interface ProcessingLog {
  id: string;
  stage: string;
  status: string;
  message?: string | null;
  confidence?: number | null;
  created_at: string;
}

export interface DocumentUploadRequest {
  file: File;
}

/** Client-side view model — the backend's /documents and /search endpoints
 * return different shapes (a plain list vs a Page envelope); documentService
 * normalizes both into this. */
export interface DocumentListResponse {
  documents: Document[];
  total: number;
  limit: number;
  offset: number;
}

export interface DocumentFilters {
  document_type?: DocumentType;
  processing_status?: ProcessingStatus;
  date_from?: string;
  date_to?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

// ── Lab Reports ─────────────────────────────────

export interface LabResult {
  id: string;
  test_name_raw: string;
  test_name_normalized?: string | null;
  result_value_raw?: string | null;
  result_value_numeric?: number | null;
  unit_raw?: string | null;
  unit_normalized?: string | null;
  reference_range_raw?: string | null;
  flag: ResultFlag;
  confidence?: number | null;
  validation_status: ValidationStatus;
}

export interface LabReport {
  id: string;
  document_id: string;
  patient_name?: string | null;
  doctor_name?: string | null;
  laboratory_name?: string | null;
  report_date?: string | null;
  results: LabResult[];
}

// ── Prescriptions ───────────────────────────────

export interface Medicine {
  id: string;
  medicine_name_raw: string;
  medicine_name_normalized?: string | null;
  dosage_raw?: string | null;
  frequency_normalized?: string | null;
  duration_raw?: string | null;
  duration_days?: number | null;
  instructions?: string | null;
  confidence?: number | null;
  validation_status: ValidationStatus;
}

export interface Prescription {
  id: string;
  document_id: string;
  patient_name?: string | null;
  doctor_name?: string | null;
  prescription_date?: string | null;
  notes?: string | null;
  medicines: Medicine[];
}

// ── Diagnoses ───────────────────────────────────

export interface Diagnosis {
  id: string;
  document_id: string;
  condition_raw: string;
  condition_normalized?: string | null;
  doctor_name?: string | null;
  diagnosis_date?: string | null;
  notes?: string | null;
  confidence?: number | null;
  validation_status: ValidationStatus;
}

// ── Medical Reports (consultation / scan / discharge / insurance / other) ──

export interface MedicalReport {
  id: string;
  document_id: string;
  report_type: DocumentType;
  doctor_name?: string | null;
  hospital_name?: string | null;
  report_date?: string | null;
  summary_text?: string | null;
  findings?: Record<string, unknown> | null;
  confidence?: number | null;
}

// ── Medical Expenses ────────────────────────────

export interface ExpenseItem {
  id: string;
  description: string;
  quantity?: number | null;
  unit_price?: number | null;
  amount: number;
}

export interface MedicalExpense {
  id: string;
  vault_id: string;
  document_id?: string | null;
  expense_date: string;
  category: ExpenseCategory;
  hospital_name?: string | null;
  amount: number;
  currency: string;
  insurance_covered: number;
  patient_paid: number;
  notes?: string | null;
  created_at: string;
  items: ExpenseItem[];
}

export interface CreateExpenseRequest {
  expense_date: string;
  category: ExpenseCategory;
  hospital_name?: string;
  amount: number;
  insurance_covered?: number;
  patient_paid?: number;
  notes?: string;
}

export interface MonthlyExpense {
  month: string;
  amount: number;
}

export interface ExpenseSummary {
  total: number;
  current_month_total: number;
  current_year_total: number;
  insurance_covered: number;
  out_of_pocket: number;
  by_category: Partial<Record<ExpenseCategory, number>>;
  by_month: MonthlyExpense[];
}

// ── Timeline ────────────────────────────────────

export interface TimelineEvent {
  id: string;
  vault_id: string;
  document_id?: string | null;
  event_type: TimelineEventType;
  event_date: string;
  title: string;
  description?: string | null;
  event_metadata?: Record<string, unknown> | null;
  created_at: string;
}

export interface TimelineFilters {
  event_type?: TimelineEventType;
  document_type?: DocumentType;
  date_from?: string;
  date_to?: string;
}

// ── Health Summary ──────────────────────────────

/** The exact structured facts the backend fed to the LLM — see
 * summary_service.build_structured_context in the backend. Every fact
 * carries a source_document_id for traceability back to the original file. */
export interface StructuredSummaryData {
  known_conditions: { condition: string; date: string | null; source_document_id: string }[];
  recent_investigations: {
    test_name: string;
    result: string | null;
    unit: string | null;
    flag: ResultFlag;
    date: string | null;
    source_document_id: string;
  }[];
  current_medications: {
    medicine: string;
    dosage: string | null;
    frequency: string | null;
    source_document_id: string;
  }[];
  recent_consultations: { date: string | null; doctor: string | null; source_document_id: string }[];
  recent_medical_events: { date: string; type: TimelineEventType; title: string }[];
  recent_expenses_total: number;
  available_documents: number;
}

export interface HealthSummary {
  id: string;
  vault_id: string;
  version: number;
  summary_text: string;
  structured_data: StructuredSummaryData | null;
  model_used: string;
  created_at: string;
}

export interface GenerateSummaryRequest {
  shared_access_id?: string;
}

// ── Sharing ─────────────────────────────────────

export interface SharedAccess {
  id: string;
  vault_id: string;
  owner_id: string;
  shared_with_user_id?: string | null;
  shared_with_email?: string | null;
  role: VaultRole;
  allowed_document_types?: DocumentType[] | null;
  status: ShareStatus;
  expires_at?: string | null;
  created_at: string;
}

export interface CreateShareRequest {
  shared_with_email: string;
  role: VaultRole;
  allowed_document_types?: DocumentType[];
  document_ids?: string[];
  expires_at?: string;
}

// ── Search ──────────────────────────────────────

export interface Page<T> {
  items: T[];
  total: number;
  limit: number;
  offset: number;
}

export interface SearchFilters {
  q?: string;
  document_type?: DocumentType;
  date_from?: string;
  date_to?: string;
  limit?: number;
  offset?: number;
}

// ── API Response wrappers ───────────────────────

export interface ApiError {
  status: number;
  message: string;
  detail?: string;
}

export type AsyncState<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'success'; data: T }
  | { status: 'error'; error: string };
